import os,time,urllib.request,urllib.error
for _ in range(120):
    req=urllib.request.Request("http://127.0.0.1:8000/tasks",headers={"Authorization":"Bearer "+os.environ["LAB_ALICE_TOKEN"]})
    try:
        with urllib.request.urlopen(req,timeout=3) as r: print(time.strftime("%H:%M:%S",time.gmtime()),r.status,flush=True)
    except urllib.error.HTTPError as e: print(time.strftime("%H:%M:%S",time.gmtime()),e.code,flush=True)
    except (OSError,TimeoutError) as e: print(time.strftime("%H:%M:%S",time.gmtime()),type(e).__name__,flush=True)
    time.sleep(1)
PY
